      if (candidates !== null || ballots.length > 0) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        throw new ElectionError('expected candidates <name>...', lineNumber)
      }
