      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new ElectionError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new ElectionError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
      }
      candidates = names
      continue
    }

    if (directive === 'ballot') {
      if (candidates === null) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new ElectionError('expected ballot <count> <candidate>...', lineNumber)
      }
      const countText = tokens[1]
      if (!COUNT_PATTERN.test(countText)) {
        throw new ElectionError('count must be a positive integer', lineNumber)
      }
      const count = Number(countText)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ElectionError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ElectionError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
      continue
    }

    throw new ElectionError(`unknown directive ${directive}`, lineNumber)
  }

  if (candidates === null) {
    throw new Error('no candidates')
  }

  return { candidates, ballots }
