{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-0MzUlm/src/election.js","content":"/**
 * Count an election by instant-runoff elimination. Returns the list of
 * rounds counted, each holding the vote tally per continuing candidate,
 * the exhausted count, and the name eliminated afterwards (or null for
 * the final round), plus the overall winner (or null).
 */
export function countElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const tally = new Map()
    for (const name of continuing) tally.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        tally.set(choice, tally.get(choice) + ballot.count)
      }
    }

    history.push(tally)
    const active = [...tally.values()].reduce((a, b) => a + b, 0)

    let roundWinner = null
    if (active > 0) {
      for (const [name, votes] of tally) {
        if (votes * 2 > active) {
          roundWinner = name
          break
        }
      }
    }

    if (roundWinner !== null) {
      rounds.push({ tally, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    if (active === 0) {
      rounds.push({ tally, exhausted, eliminated: null })
      break
    }

    const eliminated = selectEliminated(continuing, history)
    rounds.push({ tally, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

function selectEliminated(continuing, history) {
  const currentTally = history[history.length - 1]
  const fewest = Math.min(...[...continuing].map((name) => currentTally.get(name)))
  let group = [...continuing].filter((name) => currentTally.get(name) === fewest)

  let narrowed = true
  while (narrowed && group.length > 1) {
    narrowed = false
    for (const tally of history) {
      const counts = group.map((name) => tally.get(name))
      const min = Math.min(...counts)
      if (!counts.every((c) => c === min)) {
        group = group.filter((name) => tally.get(name) === min)
        narrowed = true
        break
      }
    }
  }

  if (group.length === 1) return group[0]
  return group.slice().sort().reverse()[0]
}
"}

