{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-0MzUlm/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parse.js'
import { countElection } from './election.js'
import { ElectionError } from './errors.js'

function readStdin() {
  const fs = require_fs()
  return fs.readFileSync(0, 'utf8')
}

function require_fs() {
  // eslint-disable-next-line global-require
  return globalThis.process.binding ? require('node:fs') : require('node:fs')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatRound(round) {
  const entries = [...round.tally.entries()]
  entries.sort((a, b) => (b[1] - a[1]) || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${round.exhausted}`)
  return parts.join(' ')
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ElectionError) {
      fail(`line ${err.line}: ${err.message}`)
    } else {
      fail(err.message)
    }
    return
  }

  const { rounds, winner } = countElection(election)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      output.push(`round ${index + 1}: ${formatRound(round)}`)
      if (round.eliminated !== null) output.push(`eliminated ${round.eliminated}`)
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(output.join('\n') + '\n')
}

